param([string]$GameRoot='', [switch]$HubConfirmed, [switch]$NoPause)
$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot '..\Modules\OwnedModFiles.ps1');$identity='thief2014vr';$receipt=Join-Path $PSScriptRoot '.installed_path'
function Finish([int]$c){if(-not $NoPause){Read-Host 'Press Enter to exit'|Out-Null};exit $c}
function Test-Root([string]$p){$p -and (Test-Path (Join-Path $p 'Binaries2\Win64\Shipping-ThiefGame.exe')) -and (Test-Path (Join-Path $p ".pcvrhub_${identity}_ownership.csv"))}
if(-not(Test-Root $GameRoot) -and (Test-Path $receipt)){$GameRoot=([IO.File]::ReadAllText($receipt)).Trim().Trim('"')};if(-not(Test-Root $GameRoot)){Write-Host '  No Hub-owned ThiefVR installation was found.' -ForegroundColor Yellow;Finish 0}
if(Get-Process -Name 'Shipping-ThiefGame' -ErrorAction SilentlyContinue){Write-Host '  [XX] Close Thief before removing VR mode.' -ForegroundColor Red;Finish 1};if(-not $HubConfirmed -and (Read-Host "Remove Hub-owned ThiefVR files from '$GameRoot'? Type REMOVE") -cne 'REMOVE'){Finish 0}
$win=Join-Path $GameRoot 'Binaries2\Win64';$configure=Join-Path $win 'ThiefVR-HubLauncher\configure-stereo.ps1';$graphics=Join-Path $win 'ThiefVR-backup\graphics.json';if((Test-Path $configure) -and (Test-Path $graphics)){try{& $configure -GameDirectory $win -Restore;Remove-Item $graphics -Force -ErrorAction SilentlyContinue}catch{Write-Host "  [!!] Stereo registry restore needs attention: $($_.Exception.Message)" -ForegroundColor Yellow}}
$r=Uninstall-OwnedModPayload -GameRoot $GameRoot -Identity $identity;if(-not $r.Found){throw 'The ownership manifest disappeared before removal.'};if($r.Preserved -eq 0){Remove-Item (Join-Path $GameRoot '.pcvrhub_version') -Force -ErrorAction SilentlyContinue;Remove-Item $receipt -Force -ErrorAction SilentlyContinue};Write-Host "  [OK] Removed $($r.Removed), restored $($r.Restored), preserved $($r.Preserved)." -ForegroundColor Green;Write-Host '  Thief, saves and unrelated files remain installed.' -ForegroundColor Gray;Finish 0
